-- letsboulder: evidence-based schema audit, 2026-09-07.
-- Migration filename generated by the pinned CLI in CI run 34205742649.
-- Apply through staging, then the main production workflow. Never run through MCP.
-- Baseline inspected: both projects through 20260830143000; app main 778e8213.
-- Forward-only and repeatable. No tables, columns, route geometry, or logs are deleted.
-- Data corrections: orphan creator UUIDs become NULL; derived vote summaries are rebuilt.
-- Ordinary index builds suit the audited ~10.6 MiB application schema. They block
-- writes while building. Reassess size/locking if deployment is substantially delayed.
-- This transaction fails rather than waiting indefinitely for conflicting locks.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
SET LOCAL search_path = public, pg_catalog;

-- 1. Remove table-wide privileges that client API roles do not need.
-- RLS does not protect TRUNCATE/REFERENCES. MAINTAIN is also unnecessary on PG17.
REVOKE TRUNCATE, REFERENCES, TRIGGER, MAINTAIN ON ALL TABLES IN SCHEMA public
  FROM PUBLIC, anon, authenticated;
-- Existing postgres defaults already deny client access; make that contract explicit.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE ALL ON TABLES FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE ALL ON SEQUENCES FROM PUBLIC, anon, authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres
  REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon, authenticated;
-- Managed supabase_admin defaults are intentionally outside this migration's scope.

-- Reconcile staging-only DML grants with the production contract; preserve column grants.

REVOKE DELETE, INSERT, UPDATE ON TABLE public."admin_actions" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."climb_corrections" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."climb_verifications" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."climb_video_betas" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."climbs" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."comments" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."community_place_follows" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."community_post_comments" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."community_posts" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."correction_votes" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."crags" FROM "anon";

REVOKE DELETE, INSERT, SELECT, UPDATE ON TABLE public."deleted_accounts" FROM "anon";

REVOKE DELETE, INSERT, SELECT, UPDATE ON TABLE public."deleted_accounts" FROM "authenticated";

REVOKE DELETE, INSERT, SELECT, UPDATE ON TABLE public."deletion_requests" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."grade_votes" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."grades" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."images" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."notifications" FROM "anon";

REVOKE INSERT ON TABLE public."notifications" FROM "authenticated";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."places" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."product_clicks" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."product_clicks" FROM "authenticated";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."route_grades" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."route_lines" FROM "anon";

REVOKE DELETE, INSERT, UPDATE ON TABLE public."user_climbs" FROM "anon";

-- 2. Missing FK indexes: 56 observed gaps plus the new crag editor FK.
-- A different valid full B-tree with the same leading key already covers a FK.
-- Do not duplicate that index. Fail on a conflicting requested name instead of
-- silently treating IF NOT EXISTS as proof of the index definition.
DO $indexes$
DECLARE r record; table_oid oid; key_numbers smallint[]; named_oid oid;
BEGIN
  FOR r IN SELECT * FROM (VALUES

('climbs', ARRAY['sector_id']::text[], 'climbs_sector_id_idx'),
    ('contribution_bounties', ARRAY['completed_by_user_id']::text[], 'contribution_bounties_completed_by_user_id_idx'),
    ('contribution_bounties', ARRAY['completed_event_id']::text[], 'contribution_bounties_completed_event_id_idx'),
    ('contribution_bounties', ARRAY['crag_id']::text[], 'contribution_bounties_crag_id_idx'),
    ('contribution_bounties', ARRAY['created_by_event_id']::text[], 'contribution_bounties_created_by_event_id_idx'),
    ('contribution_bounties', ARRAY['place_id']::text[], 'contribution_bounties_place_id_idx'),
    ('contribution_events', ARRAY['climb_id']::text[], 'contribution_events_climb_id_idx'),
    ('contribution_events', ARRAY['crag_id']::text[], 'contribution_events_crag_id_idx'),
    ('contribution_events', ARRAY['image_id']::text[], 'contribution_events_image_id_idx'),
    ('countries', ARRAY['region_id']::text[], 'countries_region_id_idx'),
    ('crag_images', ARRAY['sector_id']::text[], 'crag_images_sector_id_idx'),
    ('crag_maintainers', ARRAY['assigned_by']::text[], 'crag_maintainers_assigned_by_idx'),
    ('crag_maintainers', ARRAY['user_id']::text[], 'crag_maintainers_user_id_idx'),
    ('crag_metadata_proposals', ARRAY['approved_commit_id']::text[], 'crag_metadata_proposals_approved_commit_id_idx'),
    ('crag_metadata_proposals', ARRAY['base_revision_id']::text[], 'crag_metadata_proposals_base_revision_id_idx'),
    ('crag_metadata_proposals', ARRAY['reviewer_id']::text[], 'crag_metadata_proposals_reviewer_id_idx'),
    ('crag_metadata_proposals', ARRAY['source_image_id']::text[], 'crag_metadata_proposals_source_image_id_idx'),
    ('crag_publication_events', ARRAY['changed_by']::text[], 'crag_publication_events_changed_by_idx'),
    ('crag_reports', ARRAY['moderator_id']::text[], 'crag_reports_moderator_id_idx'),
    ('crags', ARRAY['created_by']::text[], 'crags_created_by_idx'),
    ('crags', ARRAY['published_by']::text[], 'crags_published_by_idx'),
    ('crags', ARRAY['reviewed_by']::text[], 'crags_reviewed_by_idx'),
    ('deletion_requests', ARRAY['user_id']::text[], 'deletion_requests_user_id_idx'),
    ('images', ARRAY['last_edited_by']::text[], 'images_last_edited_by_idx'),
    ('images', ARRAY['upload_crag_id']::text[], 'images_upload_crag_id_idx'),
    ('images', ARRAY['upload_draft_id']::text[], 'images_upload_draft_id_idx'),
    ('media_deletion_jobs', ARRAY['replay_of_job_id']::text[], 'media_deletion_jobs_replay_of_job_id_idx'),
    ('media_jobs', ARRAY['replay_of_job_id']::text[], 'media_jobs_replay_of_job_id_idx'),
    ('regions', ARRAY['un_region_name']::text[], 'regions_un_region_name_idx'),
    ('saved_climbs', ARRAY['climb_id']::text[], 'saved_climbs_climb_id_idx'),
    ('saved_crags', ARRAY['crag_id']::text[], 'saved_crags_crag_id_idx'),
    ('sectors', ARRAY['crag_id']::text[], 'sectors_crag_id_idx'),
    ('submission_collaborator_invites', ARRAY['created_by']::text[], 'submission_collaborator_invites_created_by_idx'),
    ('submission_collaborators', ARRAY['created_by']::text[], 'submission_collaborators_created_by_idx'),
    ('submission_draft_collaborator_invites', ARRAY['created_by']::text[], 'submission_draft_collaborator_invites_created_by_idx'),
    ('submission_draft_collaborators', ARRAY['created_by']::text[], 'submission_draft_collaborators_created_by_idx'),
    ('submission_draft_images', ARRAY['linked_crag_image_id']::text[], 'submission_draft_images_linked_crag_image_id_idx'),
    ('submission_draft_images', ARRAY['linked_image_id']::text[], 'submission_draft_images_linked_image_id_idx'),
    ('submission_draft_routes', ARRAY['created_by']::text[], 'submission_draft_routes_created_by_idx'),
    ('submission_draft_routes', ARRAY['updated_by']::text[], 'submission_draft_routes_updated_by_idx'),
    ('submission_drafts', ARRAY['last_edited_by']::text[], 'submission_drafts_last_edited_by_idx'),
    ('topo_replacement_routes', ARRAY['climb_id']::text[], 'topo_replacement_routes_climb_id_idx'),
    ('topo_replacement_routes', ARRAY['draft_route_id']::text[], 'topo_replacement_routes_draft_route_id_idx'),
    ('topo_replacements', ARRAY['created_by']::text[], 'topo_replacements_created_by_idx'),
    ('topo_replacements', ARRAY['published_by']::text[], 'topo_replacements_published_by_idx'),
    ('topo_replacements', ARRAY['replacement_image_id']::text[], 'topo_replacements_replacement_image_id_idx'),
    ('topo_route_line_tombstones', ARRAY['climb_id']::text[], 'topo_route_line_tombstones_climb_id_idx'),
    ('topo_route_line_tombstones', ARRAY['deleted_by']::text[], 'topo_route_line_tombstones_deleted_by_idx'),
    ('topo_route_line_tombstones', ARRAY['image_id']::text[], 'topo_route_line_tombstones_image_id_idx'),
    ('topo_route_line_tombstones', ARRAY['replacement_id']::text[], 'topo_route_line_tombstones_replacement_id_idx'),
    ('un_regions', ARRAY['continent_name']::text[], 'un_regions_continent_name_idx'),
    ('user_place_contributor_scores', ARRAY['place_id']::text[], 'user_place_contributor_scores_place_id_idx'),
    ('wiki_entity_revisions', ARRAY['parent_revision_id']::text[], 'wiki_entity_revisions_parent_revision_id_idx'),
    ('wiki_entity_revisions', ARRAY['restored_from_revision_id']::text[], 'wiki_entity_revisions_restored_from_revision_id_idx'),
    ('wiki_entity_revisions', ARRAY['supersedes_revision_id']::text[], 'wiki_entity_revisions_supersedes_revision_id_idx'),
    ('wiki_revision_merge_parents', ARRAY['parent_revision_id']::text[], 'wiki_revision_merge_parents_parent_revision_id_idx'),
    ('crags', ARRAY['last_edited_by']::text[], 'crags_last_edited_by_idx')

) AS planned(table_name, column_names, index_name)
  LOOP
    table_oid := to_regclass(format('public.%I', r.table_name));
    IF table_oid IS NULL THEN RAISE EXCEPTION 'Missing table %', r.table_name; END IF;
    SELECT array_agg(a.attnum ORDER BY k.ord) INTO key_numbers
    FROM unnest(r.column_names) WITH ORDINALITY AS k(name, ord)
    JOIN pg_attribute a ON a.attrelid = table_oid AND a.attname = k.name AND NOT a.attisdropped;
    IF cardinality(key_numbers) IS DISTINCT FROM cardinality(r.column_names) THEN
      RAISE EXCEPTION 'Missing FK columns on %', r.table_name;
    END IF;
    named_oid := to_regclass(format('public.%I', r.index_name));
    IF named_oid IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid
      JOIN pg_am am ON am.oid = c.relam
      WHERE i.indexrelid = named_oid AND i.indrelid = table_oid
        AND i.indisvalid AND i.indisready AND i.indpred IS NULL
        AND i.indexprs IS NULL AND am.amname = 'btree'
        AND i.indnkeyatts = cardinality(key_numbers)
        AND (i.indkey::smallint[])[0:cardinality(key_numbers)-1] @> key_numbers
    ) THEN RAISE EXCEPTION 'Conflicting index definition: %', r.index_name; END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid = i.indexrelid
      JOIN pg_am am ON am.oid = c.relam
      WHERE i.indrelid = table_oid AND i.indisvalid AND i.indisready
        AND i.indpred IS NULL AND i.indexprs IS NULL AND am.amname = 'btree'
        AND (i.indkey::smallint[])[0:cardinality(key_numbers)-1] @> key_numbers
    ) THEN
      EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I (%s)',
        r.index_name, r.table_name,
        (SELECT string_agg(format('%I', n), ', ') FROM unnest(r.column_names) AS n));
    END IF;
  END LOOP;
END;
$indexes$;

-- Standalone duplicates, not constraint-backed indexes. RESTRICT is intentional.
-- The primary key and username unique constraint retain their enforcement.
DO $duplicates$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('profiles_id_key', 'profiles_pkey', true),
    ('idx_profiles_username', 'profiles_username_key', false)
  ) AS duplicates(redundant, retained, redundant_unique)
  LOOP
    IF to_regclass(format('public.%I', r.redundant)) IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM pg_index a JOIN pg_index b ON b.indrelid = a.indrelid
        JOIN pg_class ac ON ac.oid = a.indexrelid JOIN pg_class bc ON bc.oid = b.indexrelid
        WHERE a.indexrelid = to_regclass(format('public.%I', r.redundant))
          AND b.indexrelid = to_regclass(format('public.%I', r.retained))
          AND a.indrelid = 'public.profiles'::regclass
          AND a.indkey = b.indkey AND a.indclass = b.indclass
          AND a.indcollation = b.indcollation AND a.indoption = b.indoption
          AND ac.relam = bc.relam AND a.indpred IS NULL AND b.indpred IS NULL
          AND a.indexprs IS NULL AND b.indexprs IS NULL
          AND a.indisunique = r.redundant_unique AND b.indisunique
          AND a.indnkeyatts = b.indnkeyatts AND a.indnatts = b.indnatts
          AND NOT a.indisreplident AND NOT a.indisclustered
          AND b.indisvalid AND b.indisready
          AND NOT EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = a.indexrelid)
      ) THEN RAISE EXCEPTION 'Unsafe duplicate index removal: %', r.redundant; END IF;
      EXECUTE format('DROP INDEX IF EXISTS public.%I RESTRICT', r.redundant);
    END IF;
  END LOOP;
END;
$duplicates$;

-- 3. Equivalent policy cleanup and statement-level identity evaluation.
-- Preserve role lists, permissive/restrictive status, and correlated access checks.
-- Only auth.uid/auth.role/auth.jwt and the STABLE, argument-free admin helper
-- become initplans. Helpers taking a row ID MUST stay correlated.

ALTER POLICY "Authenticated create correction" ON public."climb_corrections"
  WITH CHECK ((((SELECT auth.role()) = 'authenticated'::text) AND ((SELECT auth.uid()) = user_id)));

ALTER POLICY "Authenticated create verification" ON public."climb_verifications"
  WITH CHECK ((((SELECT auth.role()) = 'authenticated'::text) AND ((SELECT auth.uid()) = user_id)));

ALTER POLICY "Authenticated delete own verification" ON public."climb_verifications"
