-- Storage policies differ between production and staging. Optimize only policies
-- actually present, with explicit audited expressions; do not create legacy access.
DO $storage$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage'
    AND tablename = 'objects' AND policyname = 'Authenticated users can upload') THEN
    ALTER POLICY "Authenticated users can upload" ON storage.objects
      WITH CHECK (bucket_id = 'route-uploads' AND (SELECT auth.role()) = 'authenticated');
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage'
    AND tablename = 'objects' AND policyname = 'Route uploads read gated') THEN
    ALTER POLICY "Route uploads read gated" ON storage.objects USING (
      bucket_id = 'route-uploads' AND (
        split_part(name, '/', 1) = (SELECT auth.uid())::text OR EXISTS (
          SELECT 1 FROM public.images i WHERE i.storage_bucket = 'route-uploads'
            AND i.storage_path = objects.name
            AND COALESCE(i.moderation_status, 'pending') = 'approved'
        )
      )
    );
  END IF;
END;
$storage$;
ALTER POLICY "Avatar uploads delete own folder" ON storage.objects
  USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
ALTER POLICY "Avatar uploads insert own folder" ON storage.objects
  WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
ALTER POLICY "Avatar uploads read own folder" ON storage.objects
  USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);

-- 4. Referential integrity with content-preserving account deletion.
-- Lock both sides before orphan checks/repair so concurrent user deletion cannot
-- race the migration. These are small tables; locks last until COMMIT.
LOCK TABLE auth.users IN SHARE ROW EXCLUSIVE MODE;
LOCK TABLE public.climbs, public.images, public.crags IN SHARE ROW EXCLUSIVE MODE;

-- Four production climbs referenced two nonexistent accounts at audit time.
-- Clear only dangling attribution. IDs, content, geometry, and user logs are retained.
UPDATE public.climbs c SET user_id = NULL
WHERE c.user_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = c.user_id);

DO $attribution$
DECLARE r record; existing pg_constraint%ROWTYPE;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('climbs', 'user_id', 'climbs_user_id_fkey', 'SET NULL', 'n'),
    ('images', 'created_by', 'images_created_by_fkey', 'SET NULL', 'n'),
    ('crags', 'last_edited_by', 'crags_last_edited_by_fkey', 'SET NULL', 'n'),
    ('images', 'last_edited_by', 'images_last_edited_by_fkey', 'SET NULL', 'n'),
    ('submission_collaborators', 'created_by', 'submission_collaborators_created_by_fkey', 'SET NULL', 'n'),
    ('submission_collaborator_invites', 'created_by', 'submission_collaborator_invites_created_by_fkey', 'SET NULL', 'n'),
    ('submission_draft_collaborators', 'created_by', 'submission_draft_collaborators_created_by_fkey', 'SET NULL', 'n'),
    ('submission_draft_collaborator_invites', 'created_by', 'submission_draft_collaborator_invites_created_by_fkey', 'SET NULL', 'n'),
    ('user_climbs', 'user_id', 'user_climbs_user_id_fkey', 'CASCADE', 'c')
  ) AS changes(table_name, column_name, constraint_name, delete_action, delete_code)
  LOOP
    SELECT c.* INTO existing FROM pg_constraint c
    WHERE c.conrelid = to_regclass(format('public.%I', r.table_name))
      AND c.conname = r.constraint_name;
    IF FOUND THEN
      IF existing.contype <> 'f' OR existing.confrelid <> 'auth.users'::regclass
        OR existing.conkey <> ARRAY[(SELECT attnum FROM pg_attribute
          WHERE attrelid = existing.conrelid AND attname = r.column_name)]::smallint[]
        OR existing.confkey <> ARRAY[(SELECT attnum FROM pg_attribute
          WHERE attrelid = 'auth.users'::regclass AND attname = 'id')]::smallint[]
        OR existing.condeferrable OR existing.confupdtype <> 'a'
        OR existing.confmatchtype <> 's' THEN
        RAISE EXCEPTION 'Unexpected FK contract: %', r.constraint_name;
      END IF;
      IF existing.confdeltype::text <> r.delete_code THEN
        EXECUTE format('ALTER TABLE public.%I DROP CONSTRAINT IF EXISTS %I RESTRICT',
          r.table_name, r.constraint_name);
      ELSE
        EXECUTE format('ALTER TABLE public.%I VALIDATE CONSTRAINT %I', r.table_name, r.constraint_name);
        CONTINUE;
      END IF;
    END IF;
    EXECUTE format('ALTER TABLE public.%I ADD CONSTRAINT %I FOREIGN KEY (%I) REFERENCES auth.users(id) ON DELETE %s NOT VALID',
      r.table_name, r.constraint_name, r.column_name, r.delete_action);
    EXECUTE format('ALTER TABLE public.%I VALIDATE CONSTRAINT %I', r.table_name, r.constraint_name);
  END LOOP;
END;
$attribution$;
-- user_climbs are deleted ONLY when that account is physically deleted; this
-- matches delete_account_atomic's existing explicit log deletion. No logs change now.
-- Retained audit IDs (deleted_accounts/admin_actions) remain deliberate exceptions.

-- 5. Deterministic, single-grouping consensus summaries.
-- The old trigger counted the winning grade only and scanned votes repeatedly.
-- Serialize recomputation on each parent climb; handle OLD and NEW parents if moved.
-- This privileged trigger can write only derived consensus fields and is not an RPC.
CREATE OR REPLACE FUNCTION public.update_climb_consensus_safe()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $function$
DECLARE target_ids uuid[]; target_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN target_ids := ARRAY[NEW.climb_id];
  ELSIF TG_OP = 'DELETE' THEN target_ids := ARRAY[OLD.climb_id];
  ELSE target_ids := ARRAY[OLD.climb_id, NEW.climb_id]; END IF;
  FOR target_id IN SELECT DISTINCT id FROM unnest(target_ids) AS ids(id)
    WHERE id IS NOT NULL ORDER BY id
  LOOP
    PERFORM 1 FROM public.climbs WHERE id = target_id FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;
    WITH counts AS MATERIALIZED (
      SELECT grade, count(*) AS votes FROM public.grade_votes
      WHERE climb_id = target_id GROUP BY grade
    ), summary AS (
      SELECT COALESCE(sum(votes), 0)::integer AS total,
        (SELECT grade FROM counts ORDER BY votes DESC, grade ASC LIMIT 1) AS winner,
        (SELECT count(*) > 1 FROM counts WHERE votes = (SELECT max(votes) FROM counts)) AS tied
      FROM counts
    )
    UPDATE public.climbs c SET consensus_grade = s.winner,
      total_votes = s.total, grade_tied = s.tied
    FROM summary s WHERE c.id = target_id
      AND ROW(c.consensus_grade, c.total_votes, c.grade_tied)
        IS DISTINCT FROM ROW(s.winner, s.total, s.tied);
  END LOOP;
  RETURN NULL;
END;
$function$;
REVOKE ALL ON FUNCTION public.update_climb_consensus_safe() FROM PUBLIC, anon, authenticated;

-- Repair existing derived data once; on repeat, the DISTINCT guard makes this a no-op.
LOCK TABLE public.grade_votes IN SHARE ROW EXCLUSIVE MODE;
WITH counts AS MATERIALIZED (
  SELECT climb_id, grade, count(*) AS votes FROM public.grade_votes GROUP BY climb_id, grade
), ranked AS (
  SELECT *, row_number() OVER (PARTITION BY climb_id ORDER BY votes DESC, grade ASC) AS position,
    sum(votes) OVER (PARTITION BY climb_id)::integer AS total,
    count(*) OVER (PARTITION BY climb_id, votes) > 1 AS tied
  FROM counts
), summary AS (
  SELECT c.id, r.grade, COALESCE(r.total, 0) AS total, COALESCE(r.tied, false) AS tied
  FROM public.climbs c LEFT JOIN ranked r ON r.climb_id = c.id AND r.position = 1
)
UPDATE public.climbs c SET consensus_grade = s.grade, total_votes = s.total, grade_tied = s.tied
FROM summary s WHERE c.id = s.id
  AND ROW(c.consensus_grade, c.total_votes, c.grade_tied)
    IS DISTINCT FROM ROW(s.grade, s.total, s.tied);

-- Fully qualified invoker functions need no mutable search path. Overloads matter.
ALTER FUNCTION public.get_climbs_with_consensus() SET search_path = '';
ALTER FUNCTION public.get_crag_contributor_leaderboard(uuid, integer, integer) SET search_path = '';
ALTER FUNCTION public.get_place_contributor_leaderboard(uuid, integer, integer) SET search_path = '';

-- Retire a broken runtime-DDL utility: check_definition is not an information_schema
-- column, and its old body replaced the allowed values regardless of its argument.
-- There are no repository callers or API grants. Keep the signature, fail clearly.
CREATE OR REPLACE FUNCTION public.add_correction_type_value(new_value text)
RETURNS void LANGUAGE plpgsql SET search_path = '' AS $function$
BEGIN
  RAISE EXCEPTION 'Correction types must be changed by a versioned SQL migration'
    USING ERRCODE = '0A000';
END;
$function$;
REVOKE ALL ON FUNCTION public.add_correction_type_value(text) FROM PUBLIC, anon, authenticated;

-- 6. Timestamp consistency for ordinary mutable records.
-- Preserve explicit timestamps supplied by existing app/RPC code. Do not replace
-- monotonic draft timestamps, client mutation ordering, or immutable wiki timestamps.
CREATE OR REPLACE FUNCTION public.set_record_updated_at()
RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $function$
BEGIN
  IF NEW.updated_at IS NOT DISTINCT FROM OLD.updated_at
    AND NEW IS DISTINCT FROM OLD THEN
    NEW.updated_at := statement_timestamp();
  END IF;
  RETURN NEW;
END;
$function$;
REVOKE ALL ON FUNCTION public.set_record_updated_at() FROM PUBLIC, anon, authenticated;

